/*
 * Surroundflix page hook. Generated by the Python builder; edit the
 * template in src/surroundflix/templates/page.js, not the build output.
 *
 * How it works: Cadmium (Netflix's player) serialises its manifest
 * request with JSON.stringify before encrypting and sending it. That
 * request carries a "profiles" list of the formats the browser claims to
 * support. We wrap JSON.stringify and append the Dolby Digital Plus
 * profiles to that list. Nothing in Netflix's own code is modified, so a
 * new Cadmium version does not break this unless Netflix changes the
 * request format itself.
 *
 * DRM is untouched: the audio still comes through Netflix's normal,
 * licensed playback path.
 */
(function () {
  "use strict";

  var CONFIG = /*__SURROUNDFLIX_CONFIG__*/ null;
  if (!CONFIG || window.__surroundflix) return;

  // Prefixes Netflix uses for audio profile names. A "profiles" array is
  // only touched if it already contains at least one of these, so we never
  // edit unrelated data that happens to use the same key.
  var AUDIO_PROFILE = /^(heaac|xheaac|ddplus)-/;
  var MANIFEST_KEYS = ["params", "profiles", "profileGroups"];
  var MAX_DEPTH = 5;

  var state = {
    version: CONFIG.version,
    preset: CONFIG.preset,
    requested: CONFIG.profiles.slice(),
    patchedRequests: 0,
    lastPatchedAt: null,
    lastManifestAudio: null
  };

  function log() {
    if (!CONFIG.debug) return;
    var args = Array.prototype.slice.call(arguments);
    args.unshift("[Surroundflix]");
    console.log.apply(console, args);
  }

  function isAudioProfileList(arr) {
    if (!Array.isArray(arr)) return false;
    for (var i = 0; i < arr.length; i++) {
      if (typeof arr[i] === "string" && AUDIO_PROFILE.test(arr[i])) return true;
    }
    return false;
  }

  function addProfiles(arr) {
    var added = 0;
    for (var i = 0; i < CONFIG.profiles.length; i++) {
      var p = CONFIG.profiles[i];
      if (arr.indexOf(p) === -1) {
        arr.push(p);
        added++;
      }
    }
    return added;
  }

  // Walks the request object looking for "profiles" arrays (both the old
  // flat params.profiles and the newer profileGroups[].profiles shapes).
  function walk(node, depth) {
    if (!node || typeof node !== "object" || depth > MAX_DEPTH) return 0;
    var added = 0;
    if (Array.isArray(node)) {
      for (var i = 0; i < node.length; i++) added += walk(node[i], depth + 1);
      return added;
    }
    var keys = Object.keys(node);
    for (var k = 0; k < keys.length; k++) {
      var value = node[keys[k]];
      if (keys[k] === "profiles" && isAudioProfileList(value)) {
        added += addProfiles(value);
      } else if (value && typeof value === "object") {
        added += walk(value, depth + 1);
      }
    }
    return added;
  }

  function looksLikeManifestRequest(value) {
    if (!value || typeof value !== "object" || Array.isArray(value)) return false;
    for (var i = 0; i < MANIFEST_KEYS.length; i++) {
      if (Object.prototype.hasOwnProperty.call(value, MANIFEST_KEYS[i])) return true;
    }
    return false;
  }

  // Records which audio profiles the server actually sent back, so users
  // can paste window.__surroundflix into a bug report.
  function inspectManifestResponse(value) {
    var root = value && (value.result || value);
    var tracks = root && root.audio_tracks;
    if (!Array.isArray(tracks)) return;
    var seen = [];
    for (var i = 0; i < tracks.length; i++) {
      var streams = tracks[i] && tracks[i].streams;
      if (!Array.isArray(streams)) continue;
      for (var j = 0; j < streams.length; j++) {
        var cp = streams[j] && streams[j].content_profile;
        if (cp && seen.indexOf(cp) === -1) seen.push(cp);
      }
    }
    state.lastManifestAudio = seen;
    log("audio profiles returned by Netflix:", seen);
  }

  var nativeStringify = JSON.stringify;
  var nativeParse = JSON.parse;

  function stringify(value, replacer, space) {
    try {
      if (looksLikeManifestRequest(value)) {
        var added = walk(value, 0);
        if (added > 0) {
          state.patchedRequests++;
          state.lastPatchedAt = new Date().toISOString();
          log("manifest request patched, added", added, "profile(s)");
        }
      }
    } catch (err) {
      log("patch skipped:", err);
    }
    return nativeStringify.call(this, value, replacer, space);
  }

  function parse(text, reviver) {
    var result = nativeParse.call(this, text, reviver);
    try {
      if (result && typeof result === "object" && typeof text === "string" &&
          text.indexOf("audio_tracks") !== -1) {
        inspectManifestResponse(result);
      }
    } catch (err) {
      log("inspect skipped:", err);
    }
    return result;
  }

  // Keep the wrappers looking like the originals to other page code.
  stringify.toString = function () { return nativeStringify.toString(); };
  parse.toString = function () { return nativeParse.toString(); };

  JSON.stringify = stringify;
  JSON.parse = parse;

  Object.defineProperty(window, "__surroundflix", { value: state, configurable: false });
  log("active, preset", CONFIG.preset, CONFIG.profiles);
})();
